-- Stored procedure calls, variable handling, control-flow statements
EXEC dbo.GetCustomer @Id = 42;
EXEC dbo.usp_Report @From = '2024-01-01', @To = '2024-12-31', @Region = N'EMEA';
EXECUTE sp_executesql N'SELECT * FROM dbo.Orders WHERE Id = @Id', N'@Id INT', @Id = 5;
EXEC sp_help N'dbo.Customers';
EXEC sp_rename N'dbo.Old', N'New';
DECLARE @i INT = 0;
DECLARE @name NVARCHAR(100), @total DECIMAL(18, 2) = 0;
DECLARE @t TABLE (Id INT PRIMARY KEY, Name NVARCHAR(50));
SET @i = @i + 1;
SET @name = (SELECT TOP (1) Name FROM dbo.Customers ORDER BY Id);
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
SET IDENTITY_INSERT dbo.Customers ON;
USE [Northwind];
BEGIN TRANSACTION;
COMMIT TRANSACTION;
ROLLBACK;
IF EXISTS (SELECT 1 FROM sys.tables WHERE name = N'Customers') DROP TABLE dbo.Customers;
IF @i > 0 SELECT 1 ELSE SELECT 0;
WHILE @i < 10 BEGIN SET @i += 1; END;
BEGIN TRY SELECT 1 / 0; END TRY BEGIN CATCH SELECT ERROR_NUMBER() AS Err, ERROR_MESSAGE() AS Msg; END CATCH;
RAISERROR (N'Something failed: %s', 16, 1, N'detail');
THROW 50001, N'Custom error', 1;
PRINT N'Done';
CREATE PROCEDURE dbo.GetOrders @CustomerId INT, @Status NVARCHAR(20) = NULL AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.Orders WHERE CustomerId = @CustomerId AND (@Status IS NULL OR Status = @Status); END;
CREATE OR ALTER PROCEDURE dbo.UpsertCustomer @Id INT, @Name NVARCHAR(200) AS BEGIN UPDATE dbo.Customers SET Name = @Name WHERE Id = @Id; IF @@ROWCOUNT = 0 INSERT INTO dbo.Customers (Id, Name) VALUES (@Id, @Name); END;
CREATE FUNCTION dbo.fn_Tax (@amount DECIMAL(18, 2)) RETURNS DECIMAL(18, 2) AS BEGIN RETURN @amount * 0.2; END;
CREATE FUNCTION dbo.fn_OrdersFor (@id INT) RETURNS TABLE AS RETURN (SELECT * FROM dbo.Orders WHERE CustomerId = @id);
CREATE TRIGGER dbo.trg_Customers_Audit ON dbo.Customers AFTER INSERT, UPDATE AS BEGIN INSERT INTO dbo.AuditLog (EventType) SELECT N'chg' FROM inserted; END;
GRANT SELECT, INSERT ON dbo.Customers TO [AppUser];
REVOKE DELETE ON dbo.Customers FROM [AppUser];
